const cv=document.getElementById('c'),g=cv.getContext('2d');
const W=540,H=960,TOP=274,LANE=110,N=6,BOT=TOP+LANE*N,TILE=1080,MID=TOP+LANE*3;
// centro de cada faixa (para usar na Parte 2, dos carros)
const LANE_Y=Array.from({length:N},(_,k)=>TOP+LANE*(k+.5));
let cam=0,speed=300,paused=false,fin=null,t=0;

// asfalto: manchas escuras e granulado, feito uma vez e repetido
const tile=document.createElement('canvas');tile.width=TILE;tile.height=LANE*N;
{
  const p=tile.getContext('2d'),h=tile.height;
  p.fillStyle='#3c403f';p.fillRect(0,0,TILE,h);
  for(let i=0;i<46;i++){
    const x=Math.random()*TILE,y=Math.random()*h,rx=30+Math.random()*90,ry=8+Math.random()*22,a=.1+Math.random()*.16;
    for(const d of[-TILE,0,TILE]){
      const gr=p.createRadialGradient(x+d,y,0,x+d,y,rx);
      gr.addColorStop(0,'rgba(15,18,17,'+a+')');gr.addColorStop(1,'rgba(15,18,17,0)');
      p.save();p.translate(x+d,y);p.scale(1,ry/rx);p.translate(-(x+d),-y);
      p.fillStyle=gr;p.fillRect(x+d-rx,y-rx,rx*2,rx*2);p.restore();
    }
  }
  for(let i=0;i<9000;i++){
    p.fillStyle=Math.random()<.5?'rgba(255,255,255,.04)':'rgba(0,0,0,.1)';
    p.fillRect(Math.random()*TILE,Math.random()*h,1.5,1.5);
  }
  let s=p.createLinearGradient(0,0,0,16);s.addColorStop(0,'rgba(0,0,0,.28)');s.addColorStop(1,'rgba(0,0,0,0)');
  p.fillStyle=s;p.fillRect(0,0,TILE,16);
  s=p.createLinearGradient(0,h-16,0,h);s.addColorStop(0,'rgba(0,0,0,0)');s.addColorStop(1,'rgba(0,0,0,.28)');
  p.fillStyle=s;p.fillRect(0,h-16,TILE,16);
}
const SHIRTS=['#e23a2e','#ffd400','#1f5fd1','#0a9b3c','#f4f4f4','#ff7a1a','#8f56e8'];
const SKIN=['#e0b48a','#c68b5c','#8d5a3b','#f1c9a5'];

const HZ=TOP;
const bg=new Image();let bgReady=false;bg.onload=()=>{bgReady=true};bg.src='data:image/jpeg;base64,';
function drawBg(){const th=HZ,tw=bg.width*th/bg.height;let x=-((cam*.6)%tw);for(;x<W;x+=tw)g.drawImage(bg,x,0,tw+1,th)}
function rnd(i,s){const x=Math.sin(i*127.1+s*311.7)*43758.5453;return x-Math.floor(x)}
const WALLS=['#f2d16b','#e8856b','#7fc4b0','#ece4cf','#9db7e8','#d98aa8'];
function scenery(){
  if(bgReady){drawBg();return}
  let s=g.createLinearGradient(0,0,0,HZ);s.addColorStop(0,'#4fa8ec');s.addColorStop(1,'#cfeaf8');
  g.fillStyle=s;g.fillRect(0,0,W,HZ);
  // nuvens (andam bem devagar)
  g.fillStyle='rgba(255,255,255,.85)';
  let k=Math.floor(cam*.08/260)-1;
  for(let i=k;i<k+4;i++){
    const x=i*260+60*rnd(i,1)-cam*.08,y=18+rnd(i,2)*50;
    for(const[dx,dy,r]of[[0,0,16],[18,-6,20],[40,0,15]]){g.beginPath();g.arc(x+dx,y+dy,r,0,7);g.fill()}
  }
  // prédios lá de trás (andam devagar)
  k=Math.floor(cam*.25/70)-1;
  for(let i=k;i<k+10;i++){
    const w=56+rnd(i,3)*10,h=60+rnd(i,4)*60,x=i*70-cam*.25;
    g.fillStyle='hsl('+(200+rnd(i,5)*40|0)+',28%,'+(64+rnd(i,6)*8|0)+'%)';g.fillRect(x,HZ-h,w,h);
    g.fillStyle='rgba(255,255,255,.28)';
    for(let yy=HZ-h+8;yy<HZ-10;yy+=14)for(let xx=x+6;xx<x+w-8;xx+=13)g.fillRect(xx,yy,6,7);
  }
  // casas e lojas da frente (andam mais rápido)
  k=Math.floor(cam*.6/112)-1;
  for(let i=k;i<k+7;i++){
    const x=i*112-cam*.6+4,w=100,h=56+rnd(i,7)*40,ty=rnd(i,8)*3|0,y=HZ-h;
    g.fillStyle=WALLS[rnd(i,9)*WALLS.length|0];g.fillRect(x,y,w,h);
    g.fillStyle='rgba(0,0,0,.12)';g.fillRect(x+w-10,y,10,h);
    if(ty===0){g.fillStyle='#a8452e';g.beginPath();g.moveTo(x-5,y);g.lineTo(x+w+5,y);g.lineTo(x+w/2,y-24);g.fill()}
    else{g.fillStyle='rgba(0,0,0,.28)';g.fillRect(x-3,y-6,w+6,6)}
    for(let r=0;r<Math.floor((h-30)/28);r++)for(let q=0;q<3;q++){
      g.fillStyle='#cfe8ff';g.fillRect(x+10+q*30,y+8+r*28,18,16);
      g.fillStyle='rgba(0,0,0,.3)';g.fillRect(x+10+q*30,y+22+r*28,18,2);
    }
    g.fillStyle='#5a3a24';g.fillRect(x+w/2-8,HZ-22,16,22);
    if(ty===2)for(let q=0;q<6;q++){g.fillStyle=q%2?'#fff':'#d63a2e';g.fillRect(x+w/2-24+q*8,HZ-34,8,10)}
  }
}
function draw(){
  g.setTransform(2,0,0,2,0,0);
  g.fillStyle='#0f1318';g.fillRect(0,0,W,H);
  scenery();


  // asfalto
  const ox=-(cam%TILE);
  g.drawImage(tile,ox,TOP);g.drawImage(tile,ox+TILE,TOP);

  // linhas tracejadas das faixas (pontilhado alinhado em colunas)
  const dx=-(cam%200);
  for(const k of[1,2,4,5]){
    const y=TOP+LANE*k;
    for(let x=dx-200;x<W;x+=200){
      g.fillStyle='rgba(0,0,0,.35)';g.fillRect(x+50,y+1,90,3);
      g.fillStyle='rgba(214,217,215,.9)';g.fillRect(x+50,y-2,90,3);
    }
  }
  // bordas da pista e linha dupla amarela
  g.fillStyle='#c9cbc7';g.fillRect(0,TOP-1,W,3);g.fillRect(0,BOT-2,W,3);
  g.fillStyle='#c9a41c';g.fillRect(0,MID-5,W,3);g.fillRect(0,MID+2,W,3);

  // meio-fio de baixo com as plaquinhas
  g.fillStyle='#d6cdaa';g.fillRect(0,BOT,W,H-BOT);
  g.fillStyle='#a79f7c';g.fillRect(0,BOT+2,W,3);
  const j0=Math.floor(cam/270)-1;
  for(let j=j0;j<j0+4;j++){
    const sx=j*270+120-cam;
    g.fillStyle='#4a4437';g.fillRect(sx,BOT+9,40,11);
    g.fillStyle='#d8b43a';g.fillRect(sx+10,BOT+12,20,5);
  }

  // linha de chegada quadriculada
  if(fin!==null){
    const sx=fin-cam;
    if(sx>-40&&sx<W+40){
      g.fillStyle='rgba(0,0,0,.28)';g.fillRect(sx+28,TOP,7,LANE*N);
      for(let r=0;r<Math.ceil(LANE*N/14);r++)for(let c=0;c<2;c++){
        g.fillStyle=(r+c)%2?'#1f2c25':'#efe9d2';
        g.fillRect(sx+c*14,TOP+r*14,14,Math.min(14,LANE*N-r*14));
      }
    }else if(sx<-60)fin=null;
  }
  if(startX!==null){
    const sx=startX-cam;
    if(sx>-40&&sx<W+40){
      g.fillStyle='rgba(0,0,0,.28)';g.fillRect(sx+28,TOP,7,LANE*N);
      for(let r=0;r<Math.ceil(LANE*N/14);r++)for(let c=0;c<2;c++){
        g.fillStyle=(r+c)%2?'#1f2c25':'#efe9d2';
        g.fillRect(sx+c*14,TOP+r*14,14,Math.min(14,LANE*N-r*14));
      }
    }
  }
  drawFx();
  drawCars();
  drawVignette();
  drawHud();
  drawNote();
}

// ===== PARTE 2: CARROS =====
const SPR=["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"];
const imgs=SPR.map(u=>{const i=new Image();i.src=u;return i});
const MAXC=8,LEN=16000,CAMX=330,ORD=[2,3,1,4,0,5];
const GIFTS=['presente pequeno','presente médio','presente grande'],BOOST=[40,90,180];
const COL=['#ff3b5c','#ffb400','#22c58b','#3fa7ff','#8f56e8','#f26a1b','#d9dde3','#e84fb8'];
let cars=[],queue=[],rstate='lobby',count=12,doneT=0,winner=null,ci=0,raceX0=0,startX=null;
function mkCar(name){
  const i=cars.length,row=Math.floor(i/N),slot=i%N,lane=ORD[slot],k=Math.random()*imgs.length|0;
  return{name,spr:imgs[k],L:[165,165,165,165,165,145,145,145,145,145,155,155,150,150,150,150][k],color:COL[ci++%COL.length],d:raceX0+330-row*180-slot*8,v:0,base:380+Math.random()*60,ph:Math.random()*6,boost:0,lane,y:LANE_Y[lane],lt:Math.random()};
}
function join(u){
  u=String(u||'').trim().slice(0,14);if(!u)return null;
  let c=cars.find(x=>x.name===u);if(c)return c;
  if(rstate==='lobby'&&cars.length<MAXC){if(!cars.length)raceX0=cam;startX=raceX0+360;c=mkCar(u);cars.push(c);feed(u,'entrou na pista');notify('join',u);return c}
  if(!queue.includes(u)){queue.push(u);feed(u,'entra na próxima corrida');notify('queue',u)}
  return null;
}
function handle(e){
  if(!e||!e.user)return;const c=join(e.user);
  if(e.type==='like'&&c){const n=Math.max(1,e.count|0);if(rstate==='racing')c.boost=Math.min(260,c.boost+n*1.6);feed(c.name,'+'+n+' curtidas, acelerou');notify('like',c.name,n)}
  if(e.type==='gift'&&c){const lv=Math.max(0,Math.min(2,e.level|0));if(rstate!=='done')c.boost=Math.min(260,c.boost+BOOST[lv]);feed(c.name,'mandou '+GIFTS[lv]);notify('gift',c.name,lv)}
}
function startRace(){
  if(rstate!=='lobby')return;
  if(cars.length<2){feed('Aviso','precisa de pelo menos 2 carros');return}
  rstate='racing';winner=null;fin=raceX0+LEN;
}
function resetRace(){
  cars=[];winner=null;ci=0;rstate='lobby';count=12;fin=null;startX=null;
  while(queue.length&&cars.length<MAXC){if(!cars.length)raceX0=cam;startX=raceX0+360;cars.push(mkCar(queue.shift()))}
}
function lanesStep(c,dt){
  c.lt-=dt;if(c.lt>0)return;c.lt=.35+Math.random()*.4;
  const ov=(o,m)=>Math.abs((o.d-o.L/2)-(c.d-c.L/2))<(o.L+c.L)/2+m;
  const near=l=>cars.some(o=>o!==c&&o.lane===l&&ov(o,26));
  const front=cars.some(o=>o!==c&&o.lane===c.lane&&o.d>c.d&&(o.d-o.L-c.d)<130&&o.v<c.v+15);
  if(front||Math.random()<.04){
    const o=[c.lane-1,c.lane+1].filter(l=>l>=0&&l<N&&!near(l));
    if(o.length)c.lane=o[Math.random()*o.length|0];
  }
}
function carsStep(dt){
  if(rstate==='lobby'){if(cars.length>=2){count-=dt;if(count<=0)startRace()}else count=12}
  else if(rstate==='racing'){
    for(const c of cars){
      c.boost*=Math.exp(-dt/5);
      c.v=c.base*(1+.12*Math.sin(t*1.3+c.ph))+c.boost;
      c.pd=c.d;c.d+=c.v*dt;lanesStep(c,dt);
    }
    for(const c of [...cars].sort((a,b)=>b.d-a.d)){
      let lim=1e9,sp=0;
      for(const o of cars){if(o===c||o.d<=c.pd||Math.abs(o.y-c.y)>46)continue;const l=o.d-o.L-8;if(l<lim){lim=l;sp=o.v}}
      if(c.d>lim){c.d=Math.max(lim,c.pd);c.v=Math.min(c.v,sp)}
      if(c.d>=raceX0+LEN&&!winner)winner=c;
    }
    if(winner){rstate='done';doneT=6;cars.forEach(c=>c.v=0);feed(winner.name,'venceu a corrida!');notify('win',winner.name)}
  }else{doneT-=dt;if(doneT<=0)resetRace()}
  for(const c of cars)c.y+=(LANE_Y[c.lane]-c.y)*Math.min(1,dt*4);
  if(cars.length&&rstate!=='lobby'){const lead=Math.max(...cars.map(c=>c.d));cam+=(lead-CAMX-cam)*Math.min(1,dt*4)}
  fxStep(dt);
}
function drawCars(){
  const vis=[...cars].sort((a,b)=>a.y-b.y);
  for(const c of vis){
    const sx=c.d-cam,w=c.L,h=w*c.spr.height/c.spr.width;
    if(!c.spr.width||sx<-w-80||sx>W+80)continue;
    const gy=c.y+22;
    g.fillStyle='rgba(0,0,0,.38)';g.beginPath();g.ellipse(sx-w/2,gy,w*.47,6,0,0,7);g.fill();
    const bob=c.v>40?Math.sin(t*16+c.ph)*(.6+Math.min(1,c.v/650)):0;
    const rot=-Math.min(c.boost,120)/120*.03+Math.max(-.1,Math.min(.1,(LANE_Y[c.lane]-c.y)/60));
    g.save();g.translate(sx-w*.78,gy+bob);g.rotate(rot);g.drawImage(c.spr,-w*.22,-h,w,h);g.restore();
  }
  g.textBaseline='middle';g.font='700 14px system-ui,Arial';
  const placed=[];
  for(const c of [...vis].reverse()){
    const sx=c.d-cam,w=c.L,h=w*(c.spr.height||1)/(c.spr.width||1),gy=c.y+22;
    if(sx<-w-80||sx>W+80)continue;
    const bw=Math.max(112,g.measureText(c.name).width+46);let bx=sx-w*.8,by=gy-h-40;
    const hit=(a,b)=>a.x<b.x+b.w+4&&a.x+a.w>b.x-4&&a.y<b.y+b.h+4&&a.y+a.h>b.y-4;
    for(let k=0;k<4;k++){const r=placed.find(p=>hit({x:bx,y:by,w:bw,h:34},p));if(!r)break;bx=r.x+r.w+6}
    if(placed.some(p=>hit({x:bx,y:by,w:bw,h:34},p)))by-=38;
    placed.push({x:bx,y:by,w:bw,h:34});
    g.fillStyle='rgba(8,24,24,.88)';g.beginPath();g.roundRect(bx,by,bw,34,6);g.fill();
    g.fillStyle=c.color;g.beginPath();g.arc(bx+18,by+17,11,0,7);g.fill();
    g.fillStyle='#111';g.textAlign='center';g.fillText(c.name[0].toUpperCase(),bx+18,by+18);
    g.textAlign='left';g.fillStyle='#fff';g.fillText(c.name,bx+36,by+11);
    g.fillStyle='#ffd23f';g.fillText(Math.round(c.v*.45)+' km/h',bx+36,by+26);
  }
  g.textAlign='center';
  if(rstate==='lobby'){g.fillStyle='rgba(0,0,0,.55)';g.fillRect(0,TOP+LANE*2.5-30,W,60);g.fillStyle='#fff';g.font='700 22px system-ui,Arial';
    g.fillText(cars.length>=2?'Largada em '+Math.ceil(count)+'s':'Comente para entrar na corrida',W/2,TOP+LANE*2.5)}
  if(rstate==='done'&&winner){g.fillStyle='rgba(0,0,0,.65)';g.fillRect(0,TOP+LANE*2.5-50,W,100);g.fillStyle=winner.color;g.font='700 34px system-ui,Arial';
    g.fillText(winner.name,W/2,TOP+LANE*2.5-12);g.fillStyle='#fff';g.font='700 22px system-ui,Arial';g.fillText('venceu a corrida!',W/2,TOP+LANE*2.5+24)}
}
const feedEl=document.getElementById('feed');
function feed(u,s){const li=document.createElement('li');li.textContent=u+' '+s;feedEl.prepend(li);while(feedEl.children.length>5)feedEl.lastChild.remove()}
const NAMES=['Lucas','Maria','Duda','Kaua','Bia','Gabi','Rafa','Thiago','Ana','Lari','Dani','Vitor'];
document.getElementById('ctl').addEventListener('click',e=>{
  const a=e.target.dataset.a;if(!a)return;const u=document.getElementById('user').value;
  if(a==='comment')handle({type:'comment',user:u});
  if(a==='like')handle({type:'like',user:u,count:15});
  if(a[0]==='g')handle({type:'gift',user:u,level:+a[1]});
  if(a==='rand')for(let i=0;i<5;i++)handle({type:'comment',user:NAMES[Math.random()*NAMES.length|0]+(Math.random()*90+10|0)});
  if(a==='start')startRace();
});
window.liveEvent=handle;

// ===== PARTE 3: MINIMAPA E TOP 5 =====
const MPTS=[[20,72],[38,32],[88,16],[138,30],[168,18],[192,50],[170,88],[112,98],[58,102]];
const MAPX=18,MAPY=30;
const mapPath=(()=>{
  const P=MPTS,n=P.length,pts=[];
  const cr=(a,b,c,d,t)=>.5*((2*b)+(-a+c)*t+(2*a-5*b+4*c-d)*t*t+(-a+3*b-3*c+d)*t*t*t);
  for(let i=0;i<n;i++){
    const p0=P[(i-1+n)%n],p1=P[i],p2=P[(i+1)%n],p3=P[(i+2)%n];
    for(let k=0;k<24;k++){const t=k/24;pts.push([cr(p0[0],p1[0],p2[0],p3[0],t),cr(p0[1],p1[1],p2[1],p3[1],t)])}
  }
  const cum=[0];
  for(let i=1;i<=pts.length;i++){const a=pts[i-1],b=pts[i%pts.length];cum.push(cum[i-1]+Math.hypot(b[0]-a[0],b[1]-a[1]))}
  return{pts,cum,len:cum[pts.length]};
})();
function mapAt(u){
  const L=mapPath.len*Math.min(.9999,Math.max(0,u)),n=mapPath.pts.length;
  let lo=0,hi=n;while(hi-lo>1){const m=(lo+hi)>>1;if(mapPath.cum[m]<=L)lo=m;else hi=m}
  const a=mapPath.pts[lo],b=mapPath.pts[(lo+1)%n],s=(L-mapPath.cum[lo])/((mapPath.cum[lo+1]-mapPath.cum[lo])||1);
  return[a[0]+(b[0]-a[0])*s,a[1]+(b[1]-a[1])*s];
}
function avatar(x,y,r,c){
  g.fillStyle='#14211f';g.beginPath();g.arc(x,y,r,0,7);g.fill();
  g.lineWidth=3;g.strokeStyle=c.color;g.stroke();
  g.fillStyle='#fff';g.font='700 '+(r+1)+'px system-ui,Arial';g.textAlign='center';g.textBaseline='middle';
  g.fillText(c.name[0].toUpperCase(),x,y+1);
}
function drawHud(){
  const rank=[...cars].sort((a,b)=>b.d-a.d);
  // minimapa
  g.save();g.translate(MAPX,MAPY);g.lineJoin='round';
  g.beginPath();mapPath.pts.forEach((p,i)=>i?g.lineTo(p[0],p[1]):g.moveTo(p[0],p[1]));g.closePath();
  g.strokeStyle='rgba(0,0,0,.6)';g.lineWidth=11;g.stroke();
  g.strokeStyle='#fff';g.lineWidth=6;g.stroke();
  const s=mapAt(0);g.fillStyle='#111';g.fillRect(s[0]-7,s[1]-7,14,14);g.fillStyle='#fff';g.fillRect(s[0]-7,s[1]-7,7,7);g.fillRect(s[0],s[1],7,7);
  const span=LEN-330;
  for(let i=rank.length-1;i>=0;i--){const c=rank[i],q=mapAt((c.d-(raceX0+330))/span);avatar(q[0],q[1],i?9:11,c)}
  g.restore();
  // TOP 5
  const px=W-198,py=12,pw=188;
  g.fillStyle='rgba(8,24,24,.88)';g.beginPath();g.roundRect(px,py,pw,170,10);g.fill();
  g.textAlign='left';g.textBaseline='middle';g.font='700 14px system-ui,Arial';g.fillStyle='#ffd23f';g.fillText('TOP 5',px+14,py+17);
  for(let i=0;i<5;i++){
    const y=py+46+i*25,c=rank[i];
    g.textAlign='left';g.font='700 13px system-ui,Arial';g.fillStyle='#fff';g.fillText((i+1)+'°',px+14,y);
    if(c){
      avatar(px+54,y,10,c);
      g.textAlign='left';g.font='700 13px system-ui,Arial';g.fillStyle='#fff';
      let nm=c.name;while(g.measureText(nm).width>pw-88&&nm.length>3)nm=nm.slice(0,-1);
      g.fillText(nm+(nm!==c.name?'…':''),px+72,y);
    }else{g.fillStyle='rgba(255,255,255,.35)';g.fillText('—',px+72,y)}
  }
}

// ===== EFEITOS DE VELOCIDADE =====
let camV=0,prevCam=0,parts=[];
const streaks=Array.from({length:26},()=>({x:Math.random()*W,y:TOP+Math.random()*LANE*N,l:40+Math.random()*90,f:.8+Math.random()*.9}));
const hexA=(h,a)=>{const n=parseInt(h.slice(1),16);return'rgba('+(n>>16)+','+(n>>8&255)+','+(n&255)+','+a+')'};
function fxStep(dt){
  noteStep(dt);
  camV=(cam-prevCam)/Math.max(dt,.001);prevCam=cam;
  for(const s of streaks){s.x-=camV*dt*s.f;if(s.x<-s.l){s.x=W+Math.random()*120;s.y=TOP+Math.random()*LANE*N;s.l=40+Math.random()*90}}
  if(rstate==='racing')for(const c of cars){
    c.em=(c.em||0)+dt*(5+c.v/60+c.boost*.12);
    while(c.em>=1&&parts.length<420){c.em--;parts.push({x:c.d-c.L*.86,y:c.y+19+Math.random()*3,vx:-(15+Math.random()*40),vy:-(10+Math.random()*28),r:2+Math.random()*2,age:0,life:.55+Math.random()*.5,c:c.boost>40?'#cfd8ff':'#d6d6d0'})}
  }
  for(const p of parts){p.age+=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.r+=dt*9}
  parts=parts.filter(p=>p.age<p.life);
}
function drawFx(){
  const k=Math.max(0,Math.min(1,(camV-280)/420));
  if(k>0){
    g.strokeStyle='#fff';g.lineWidth=2;
    for(const s of streaks){g.globalAlpha=.07+.28*k*(s.f-.6);g.beginPath();g.moveTo(s.x,s.y);g.lineTo(s.x+s.l*(.5+k),s.y);g.stroke()}
  }
  for(const p of parts){g.globalAlpha=Math.max(0,1-p.age/p.life)*.4;g.fillStyle=p.c;g.beginPath();g.arc(p.x-cam,p.y,p.r,0,7);g.fill()}
  g.globalAlpha=1;
}
function drawVignette(){
  const k=Math.max(0,Math.min(1,(camV-300)/400));if(k<.02)return;
  const gr=g.createRadialGradient(W/2,H/2,H*.25,W/2,H/2,H*.62);
  gr.addColorStop(0,'rgba(0,0,0,0)');gr.addColorStop(1,'rgba(0,0,0,'+(.35*k)+')');
  g.fillStyle=gr;g.fillRect(0,0,W,H);
}

// ===== AVISOS: curtidas, presentes, entradas e vencedor =====
const notes=[];let cur=null;
const NCOL={like:'#ff5fb0',gift:'#ffd23f',join:'#2ee6a6',win:'#ffd23f',queue:'#8fb8ff'};
function notify(type,name,extra){notes.push({type,name,extra});if(notes.length>5)notes.shift()}
function noteText(n){
  if(n.type==='like')return['CURTIU A LIVE','+'+n.extra+' curtidas · Curtidas aceleram seu veículo.'];
  if(n.type==='gift')return['ENVIOU UM PRESENTE',['Presente pequeno · acelera um pouco.','Presente médio · acelera bastante.','Presente grande · acelera muito!'][n.extra]];
  if(n.type==='join')return['ENTROU NA CORRIDA','Boa sorte! Curtidas e presentes aceleram seu veículo.'];
  if(n.type==='win')return['VENCEU A CORRIDA!','Uma nova corrida começa em instantes.'];
  return['NA FILA','Entra na próxima corrida.'];
}
function noteStep(dt){
  if(cur){cur.age+=dt;if(cur.age>cur.hold)cur=null}
  if(!cur&&notes.length){cur=notes.shift();cur.age=0;cur.hold=notes.length>3?1.4:3}
}
function drawNote(){
  if(!cur)return;
  const IN=.35,OUT=.3,a=cur.age,hold=cur.hold,y=192,w=520,hh=50;
  let x=10,al=1;
  if(a<IN){const e=1-Math.pow(1-a/IN,3);x=10-(1-e)*540}
  else if(a>hold-OUT)al=Math.max(0,(hold-a)/OUT);
  const col=NCOL[cur.type],tx=noteText(cur);
  g.save();g.globalAlpha=al;
  g.fillStyle='rgba(8,24,24,.9)';g.beginPath();g.roundRect(x,y,w,hh,10);g.fill();
  g.fillStyle=col;g.beginPath();g.roundRect(x,y,6,hh,3);g.fill();
  g.textBaseline='middle';g.textAlign='left';
  g.font='700 17px system-ui,Arial';g.fillStyle=col;
  const nm='@'+cur.name;g.fillText(nm,x+18,y+17);
  const nw=g.measureText(nm+' ').width;g.fillStyle='#fff';g.fillText('· '+tx[0],x+18+nw,y+17);
  g.font='600 14px system-ui,Arial';g.fillStyle='rgba(255,255,255,.75)';g.fillText(tx[1],x+18,y+37);
  g.font='22px system-ui,Arial';g.textAlign='right';
  g.fillText({like:'❤️',gift:'🎁',join:'🏁',win:'🏆',queue:'⏳'}[cur.type],x+w-14,y+hh/2);
  g.restore();
}

let last=performance.now();
function loop(n){
  const dt=Math.min(.05,(n-last)/1000);last=n;t+=dt;
  if(!cars.length&&!paused)cam+=speed*dt;
  carsStep(dt);draw();requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

document.getElementById('sp').oninput=e=>{speed=+e.target.value;document.getElementById('spv').textContent=speed};
document.getElementById('pause').onclick=e=>{paused=!paused;e.target.textContent=paused?'Continuar':'Pausar'};
document.getElementById('fin').onclick=()=>{fin=cam+W+60};